-- UPDATE preguntas.tema/subtema/tema_revisar/tema_alternativo/tema_motivo
-- Fuente: ingesta/temas_clasificacion_fir/consolidado_final.json (1033 registros)
-- Fase 4 del plan de clasificacion FIR: 5 agentes de Fase 1 (uno por convocatoria,
-- 10 areas ancla + regla de desempate formal) + 10 agentes de Fase 2 (uno por area,
-- consolidacion de subtemas finos en temas finales) + 14 correcciones manuales de
-- consistencia cruzada entre areas (Regla 3 aplicada retroactivamente).

BEGIN;

DO $$
DECLARE
  sin_tema_antes int;
BEGIN
  SELECT COUNT(*) INTO sin_tema_antes FROM public.preguntas WHERE tema IS NULL;
  IF sin_tema_antes != 1033 THEN
    RAISE EXCEPTION 'Se esperaban 1033 preguntas sin tema (segun el JSON), hay % -- abortando para no pisar filas con otro motivo.', sin_tema_antes;
  END IF;
END $$;

UPDATE public.preguntas AS p
SET tema = v.tema,
