DO $$
DECLARE
  sin_tema_despues int;
  total_filas int;
BEGIN
  SELECT COUNT(*) INTO sin_tema_despues FROM public.preguntas WHERE tema IS NULL;
  IF sin_tema_despues != 0 THEN
    RAISE EXCEPTION '% preguntas se quedaron sin tema -- abortando.', sin_tema_despues;
  END IF;

  SELECT COUNT(*) INTO total_filas FROM public.preguntas WHERE tema IS NOT NULL;
  IF total_filas != 1033 THEN
    RAISE EXCEPTION 'Se esperaban 1033 preguntas con tema tras el UPDATE, hay % -- abortando.', total_filas;
  END IF;

  RAISE NOTICE 'OK: % preguntas con tema, 0 sin clasificar.', total_filas;
END $$;

COMMIT;
